UPDATE hydra_uofs_transfer_task
SET status = #{status},
    phase = #{phase},
    message = #{message},
    error_message = #{errorMessage}
WHERE guid = #{guid}

UPDATE hydra_uofs_transfer_task
SET status = 'DONE',
    phase = 'DONE',
    result_snapshot = #{resultSnapshot},
    message = #{message}
WHERE guid = #{guid}
